def simulate(capacity, operations):
    data = [None] * capacity
    head = tail = count = 0
    result = []
    for op in operations:
        if op[0] == 'put':
            if count == capacity:
                result.append(False)
            else:
                data[tail] = op[1]
                tail = (tail + 1) % capacity
                count += 1
                result.append(True)
        else:
            if count == 0:
                result.append(None)
            else:
                result.append(data[head])
                head = (head + 1) % capacity
                count -= 1
    return result
